//GroupCompanyCode:集团ID
var iclient = KMClientInterface.getInstance();
var host = $System.host;
var api = '/QgetGroupCompanyCodeData';
var type = 'POST';
var postType = 'JSON';
var parameter = {
    GroupCompanyCode:sessionStorage.getItem("GroupCompanyCode"),
};
var data = {
    "InParam": parameter,
    "RequestType": "normal",
    "RequestID": new Date().getTime(),
};
iclient.httpRequestExec(host, api, type, data, postType, function (data)
{

    var msg = data.returnData.msg;
    var value =  data.returnData.value;
    if(msg !== 4002)
    {
        if(msg !== -1)
        {
            $(Combobox1.id).combobox
            ({
                value:value.comDatas[0].value,
                data: value.comDatas
            });
            $Variable.area=value.comDatas[0].label;
        }
        else
        {
            alert('查询无数据！');
            $(Combobox1.id).combobox
            ({
                value:'',
                data:[]
            });
        }
    }
    else
    {
        alert('查询失败！');
        $(Combobox1.id).combobox
            ({
                value:'',
                data:[]
            });
    }
});

