subscribeAlarmMsg('bj',function(data)
{


    checkSite=$('#'+Combobox5.getUIId()).textbox('getText');
    var value =data;
    var rowData=[];
    if(checkSite!='全部')
    {

        for(var i=0;i<value.length;i++)
        {
            var AlarmSiteName=value[i].N.split("_");

            if(checkSite===AlarmSiteName[0])
            {
                      value[i].companyName= AlarmSiteName[0];
                rowData.push(value[i]);
                // rowData.push(value[i]);
            }
        }
        $(Datagrid1.id).datagrid
        ({
            data:rowData
        });
    }
    else
    {
       for(var j=1;j< $Property.SiteArray.comDatas.length;j++)
        {
            for(var k=0;k<value.length;k++)
            {
                var AlarmSiteName2=value[k].N.split("_");
                if($Property.SiteArray.comDatas[j].value===AlarmSiteName2[0])
                {
                      value[k].companyName= AlarmSiteName2[0];
                    rowData.push(value[k]);
                }
            }
        }
        console.log('rowData:',rowData)
            $(Datagrid1.id).datagrid
            ({
                data:rowData
            });
    }
});

